"""Hybrid search: QMD over the Markdown knowledge base + SQLite FTS."""

from dataclasses import dataclass
from datetime import datetime

from sqlalchemy import select
from sqlalchemy.orm import Session

from wakil.app.memory_service import retrieval_rank
from wakil.config.settings import WorkspaceConfig
from wakil.integrations.qmd import qmd_search
from wakil.storage import fts
from wakil.storage.schema import Workspace


@dataclass
class SearchHit:
    kind: str  # note | memory | source
    ref: str  # note path, "memory:<id>", or "source:<id>"
    title: str
    snippet: str
    engine: str  # qmd | fts
    score: float | None = None
    state: str | None = None  # memory lifecycle state, for memory hits


def get_workspace_id(session: Session, config: WorkspaceConfig) -> int | None:
    return session.scalar(select(Workspace.id).where(Workspace.root_path == str(config.state_root)))


def search_workspace(
    session: Session,
    config: WorkspaceConfig,
    query: str,
    limit: int = 10,
    mode: str = "search",
) -> list[SearchHit]:
    """QMD results first (knowledge base is the source of truth), then FTS."""
    hits: list[SearchHit] = []
    seen_notes: set[str] = set()

    if config.qmd_enabled:
        for result in qmd_search(config.root_path, config.qmd_dir, query, limit=limit, mode=mode):
            seen_notes.add(result.path)
            hits.append(
                SearchHit(
                    kind="note",
                    ref=result.path,
                    title=result.title or result.path,
                    snippet=result.snippet,
                    engine="qmd",
                    score=result.score,
                )
            )

    workspace_id = get_workspace_id(session, config)
    if workspace_id is None:
        return hits

    for row in fts.search_notes(session, workspace_id, query, limit=limit):
        if row["ref"] in seen_notes:
            continue
        hits.append(_fts_hit("note", row))
    hits.extend(_ranked_memory_hits(fts.search_memories(session, workspace_id, query, limit=limit)))
    for row in fts.search_sources(session, workspace_id, query, limit=limit):
        hits.append(_fts_hit("source", row))

    return hits


def _ranked_memory_hits(rows: list[dict]) -> list[SearchHit]:
    """Order memory hits by lifecycle rank (durable first, faded/archived last),
    breaking ties by confidence within the same state, then by bm25 relevance."""

    def sort_key(row: dict) -> tuple[float, float]:
        return (
            retrieval_rank(row["state"], _parse_dt(row["created_at"]), row.get("confidence")),
            row["score"],
        )

    return [_fts_hit("memory", row) for row in sorted(rows, key=sort_key)]


def _parse_dt(value) -> datetime | None:
    if isinstance(value, datetime):
        return value
    try:
        return datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None


def _fts_hit(kind: str, row: dict) -> SearchHit:
    return SearchHit(
        kind=kind,
        ref=row["ref"],
        title=row["title"] or row["ref"],
        snippet=row["snippet"] or "",
        engine="fts",
        score=row["score"],
        state=row.get("state"),
    )

def discover_skill_names(context: ResolutionContext) -> list[str]:
    """Sorted, deduped candidate skill names found as immediate children of any root.

    Does not validate the skills, only enumerates directory names that look
    like skill names.
    """
    names: set[str] = set()
    for root in resolve_roots(context).roots:
        for child in root.path.iterdir():
            if child.is_dir() and SKILL_NAME_RE.match(child.name):
                names.add(child.name)
    return sorted(names)


def find_shadowed_roots(name: str, context: ResolutionContext) -> list[SkillRoot]:
    """Roots (in precedence order) where a `<name>/` subdirectory exists.

    Existence check only, no validation of the candidate directories.
    """
    validate_skill_name(name)
    return [
        root
        for root in resolve_roots(context).roots
        if (root.path / name).exists()
    ]


def default_context(
    kb_root: Path, *, environ: Mapping[str, str] | None = None
) -> ResolutionContext:
    """Build the standard `ResolutionContext` for a knowledge base."""
    env = environ if environ is not None else os.environ
    return ResolutionContext(
        kb_root=kb_root,
        user_skill_root=config_home() / "skills",
        builtin_skill_root=Path(__file__).resolve().parent,
        skill_path=env.get("WAKIL_SKILL_PATH"),
    )

@skills_app.command("list")
def skills_list(ctx: typer.Context) -> None:
    """List effective skills and their resolved source."""
    from wakil.skills.errors import SkillResolutionError
    from wakil.skills.resolver import (
        default_context,
        discover_skill_names,
        resolve_roots,
        resolve_skill,
    )

    root = _resolve_workspace(ctx)
    context = default_context(root)
    root_resolution = resolve_roots(context)
    print_root_issues(root_resolution.issues)

    rows: list[tuple[str, str, str]] = []
    for name in discover_skill_names(context):
        try:
            resolved = resolve_skill(name, context)
        except SkillResolutionError as exc:
            rows.append((name, "error", f"{exc.reason}: {exc}"))
        else:
            rows.append((resolved.name, resolved.source, str(resolved.directory)))
    print_skill_list(rows)


